import{_ as o,C as r,o as t,c as s,a9 as a,b as l,w as i,a as h,E as d,a8 as u}from"./chunks/framework.BOiBTRPC.js";const k=JSON.parse('{"title":"Intuitions — Track Overview","description":"The mental models that make the jargon click — built visually first, named second. Interactive walkthroughs of scaling, query plans, and shuffle skew.","frontmatter":{"title":"Intuitions — Track Overview","description":"The mental models that make the jargon click — built visually first, named second. Interactive walkthroughs of scaling, query plans, and shuffle skew."},"headers":[],"relativePath":"intuitions/index.md","filePath":"intuitions/index.md"}'),c={name:"intuitions/index.md"};function m(p,e,g,f,y,w){const n=r("Mermaid");return t(),s("div",null,[e[1]||(e[1]=a('<h1 id="intuitions-see-it-before-you-name-it" tabindex="-1">Intuitions: See It Before You Name It <a class="header-anchor" href="#intuitions-see-it-before-you-name-it" aria-label="Permalink to &quot;Intuitions: See It Before You Name It&quot;">​</a></h1><blockquote><p><strong>Why it matters</strong> — Most data-engineering concepts are taught backwards: jargon first, picture later, understanding maybe. This track inverts it. Every chapter starts with a system small enough to fit in your head — one machine, two tables, twenty-four dots — and lets you break it until the formal name feels obvious.</p></blockquote><h2 id="why-intuition-before-jargon" tabindex="-1">Why intuition before jargon <a class="header-anchor" href="#why-intuition-before-jargon" aria-label="Permalink to &quot;Why intuition before jargon&quot;">​</a></h2><p>You can memorize &quot;predicate pushdown reduces intermediate cardinality&quot; and still not know when it matters. But if you&#39;ve <em>watched</em> a filter node slide under a join and seen the cost bar collapse 38% in one step, the phrase is just a label for something you already own. That&#39;s the design rule here:</p><ol><li><strong>Concrete first.</strong> A tiny example you could hold in your head — not a diagram of a real cluster.</li><li><strong>Interactive second.</strong> Every chapter has a component you can poke. Press the button that breaks it; the interesting part is always what happens next.</li><li><strong>Name last.</strong> The formal term arrives <em>after</em> the picture, phrased as &quot;what you just watched is called X.&quot; That&#39;s not a gimmick — it&#39;s how the concept actually enters your long-term memory.</li><li><strong>Then reality.</strong> Once the intuition is solid, each chapter connects it to the real systems, the trade-off tables, and the production failure modes.</li></ol>',5)),(t(),l(u,null,{default:i(()=>[d(n,{id:"mermaid-36",class:"mermaid",graph:"flowchart%20LR%0A%20%20A%5B%22Concrete%20toy%3Cbr%2F%3Eone%20machine%20%C2%B7%202%20tables%20%C2%B7%2024%20dots%22%5D%20--%3E%20B%5B%22Break%20it%3Cbr%2F%3Ekill%20a%20node%20%C2%B7%20skew%20a%20key%22%5D%0A%20%20B%20--%3E%20C%5B%22Name%20it%3Cbr%2F%3Ethe%20formal%20term%20lands%22%5D%0A%20%20C%20--%3E%20D%5B%22Connect%20it%3Cbr%2F%3ESpark%20%C2%B7%20BigQuery%20%C2%B7%20real%20incidents%22%5D%0A"})]),fallback:i(()=>[...e[0]||(e[0]=[h(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<h2 id="track-map" tabindex="-1">Track map <a class="header-anchor" href="#track-map" aria-label="Permalink to &quot;Track map&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Chapter</th><th>You&#39;ll build the mental model for</th><th>The formal names that land</th></tr></thead><tbody><tr><td><a href="/Data-Knowledge/intuitions/scaling.html">Scaling: Up vs Out</a></td><td>One machine grows until it can&#39;t; a fleet absorbs a death</td><td>Shared-nothing, partial failure, diminishing returns</td></tr><tr><td><a href="/Data-Knowledge/intuitions/query-plans.html">Query Plans &amp; Optimization</a></td><td>SQL as a wish; a tree of operators getting rewritten</td><td>Logical vs physical plan, pushdown, pruning, cost model, join order</td></tr><tr><td><a href="/Data-Knowledge/intuitions/shuffle-skew.html">Shuffle, Partitioning &amp; Skew</a></td><td>24 dots hashing into 4 buckets — then one bucket overflows</td><td>Shuffle boundary, hash partitioner, straggler, salting, AQE</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">💡 How to use this track</p><p>Read these <em>before</em> the deep-dive tracks (Spark, SQL, system design). They won&#39;t teach you configs — they&#39;ll teach you what the configs are for. When a later chapter says &quot;your shuffle is skewed,&quot; you&#39;ll already have the picture.</p></div><h2 id="the-one-idea-per-visual-rule" tabindex="-1">The one-idea-per-visual rule <a class="header-anchor" href="#the-one-idea-per-visual-rule" aria-label="Permalink to &quot;The one-idea-per-visual rule&quot;">​</a></h2><p>Each interactive shows <em>one</em> idea, animated:</p><ul><li><strong>Scaling</strong> — vertical vs horizontal, and the moment a node dies under each.</li><li><strong>Query plans</strong> — the optimizer as a series of rewrites, not a black box.</li><li><strong>Shuffle</strong> — hashing as a fairness machine, skew as its failure mode.</li></ul><p>If you can explain what happened in each visual without using the jargon, the chapter worked. If you can now explain it <em>using</em> the jargon, you&#39;re interview-ready.</p><h2 id="suggested-path" tabindex="-1">Suggested path <a class="header-anchor" href="#suggested-path" aria-label="Permalink to &quot;Suggested path&quot;">​</a></h2><ol><li><a href="/Data-Knowledge/intuitions/scaling.html">Scaling</a> — 20 minutes. Why we distribute at all.</li><li><a href="/Data-Knowledge/intuitions/query-plans.html">Query plans</a> — 25 minutes. What the engine does with your SQL.</li><li><a href="/Data-Knowledge/intuitions/shuffle-skew.html">Shuffle &amp; skew</a> — 25 minutes. Where the bill and the 3am page both come from.</li></ol><p>Then move to <a href="/Data-Knowledge/spark/architecture.html">Spark architecture</a>, <a href="/Data-Knowledge/spark/execution.html">Catalyst &amp; joins</a>, or <a href="/Data-Knowledge/system-design/">system design</a> with the pictures already in place.</p>',10))])}const v=o(c,[["render",m]]);export{k as __pageData,v as default};
